        raise NotImplementedError

    @staticmethod
    def post_transition_callback(*args, **kwargs):
        raise NotImplementedError

    @staticmethod
    def _get_model_qualified_name__(sender):
        return "{}.{}".format(sender.__module__, getattr(sender, "__qualname__", sender.__name__))


